Dataspatium.assets.register("presets/api/syke-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"syke-geodata\",\n  \"name\": \"Finlands miljöcentral SYKE skyddade områden (WFS)\",\n  \"publisher\": \"Finlands miljöcentral\",\n  \"description\": \"Skyddade områden från SYKE (INSPIRE): naturskyddsområden på statens och på privat mark, Natura 2000, ödemarksområden och skyddade byggnader. Välj lager och hämta objekten. Avrinningsområden och vattendrag finns som SYKE vatten i listan över färdiga geodatakällor.\",\n  \"docs\": \"https://www.syke.fi/avointieto\",\n  \"license\": {\n    \"name\": \"CC BY 4.0\",\n    \"url\": \"https://creativecommons.org/licenses/by/4.0/\"\n  },\n  \"level\": 1,\n  \"country\": \"FI\",\n  \"baseUrl\": \"https://paikkatiedot.ymparisto.fi/geoserver/inspire_ps/wfs\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Finnish Environment Institute SYKE protected areas (WFS)\",\n      \"description\": \"Protected areas from SYKE (INSPIRE): nature reserves on state and private land, Natura 2000, wilderness areas and protected buildings. Choose a layer and fetch the features. Catchments and watercourses are SYKE vatten in the list of ready-made geodata sources.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\",\n      \"name\": \"Finnish Environment Institute SYKE protected areas (WFS)\"\n    },\n    \"nb\": {\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\",\n      \"name\": \"Finnish Environment Institute SYKE protected areas (WFS)\"\n    },\n    \"fi\": {\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\",\n      \"name\": \"Finnish Environment Institute SYKE protected areas (WFS)\"\n    },\n    \"is\": {\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\",\n      \"name\": \"Finnish Environment Institute SYKE protected areas (WFS)\"\n    }\n  }\n}\n");
